import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/35-Modularization_Execution_Checklist.html","title":"Apollo 模块化执行清单","lang":"en-US","frontmatter":{},"filePathRelative":"35-Modularization_Execution_Checklist.md","git":{"createdTime":1773758218000,"updatedTime":1773758218000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),a={name:`35-Modularization_Execution_Checklist.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="apollo-模块化执行清单" tabindex="-1"><a class="header-anchor" href="#apollo-模块化执行清单"><span>Apollo 模块化执行清单</span></a></h1><p>本清单用于跟踪从单体 <code>apollo</code> target 迁移到模块化 target 的施工顺序。</p><h2 id="phase-1-骨架完成" tabindex="-1"><a class="header-anchor" href="#phase-1-骨架完成"><span>Phase 1: 骨架完成</span></a></h2><ul><li>[x] 顶层 <code>CMakeLists.txt</code> 接入 <code>modules/</code></li><li>[x] 顶层 <code>CMakeLists.txt</code> 接入 <code>apps/</code></li><li>[x] 新增 <code>modules/base</code></li><li>[x] 新增 <code>modules/core</code></li><li>[x] 新增 <code>modules/runtime</code></li><li>[x] 新增 <code>apps/game-server</code></li><li>[x] 明确 target 命名规则</li><li>[x] 明确依赖方向</li></ul><h2 id="phase-2-基础模块抽取" tabindex="-1"><a class="header-anchor" href="#phase-2-基础模块抽取"><span>Phase 2: 基础模块抽取</span></a></h2><ul><li>[x] 盘点 <code>src/utils</code>、<code>src/apollo/utils</code> 中可下沉到 <code>base</code> 的通用能力</li><li>[x] 抽出 <code>apollo_base</code> 第一批真实源码</li><li>[x] 通过独立 smoke build 验证 <code>apollo_base -&gt; apollo_core -&gt; apollo_runtime -&gt; apollo_game_server</code></li><li>[x] 为 <code>apollo_base</code> 增加基础单元测试</li><li>[ ] 定义 <code>base/terminal</code> 与 <code>runtime/console</code> 的边界</li><li>[ ] 将 <code>Time</code>、<code>IdPool</code> 的现有调用逐步切换到 <code>apollo/base/*</code></li><li>[x] 将 <code>ThreadPool</code> 的新公共入口落到 <code>apollo/base/thread_pool.hpp</code></li></ul><h2 id="phase-3-核心模块抽取" tabindex="-1"><a class="header-anchor" href="#phase-3-核心模块抽取"><span>Phase 3: 核心模块抽取</span></a></h2><ul><li>[x] 合并并迁移 DI 能力到 <code>apollo_core</code></li><li>[x] 合并并迁移配置管理到 <code>apollo_core</code></li><li>[x] 合并并迁移日志管理到 <code>apollo_core</code></li><li>[ ] 统一生命周期与模块管理模型</li><li>[x] 为 <code>apollo_core</code> 增加最小可运行测试</li></ul><h2 id="phase-4-runtime-抽取" tabindex="-1"><a class="header-anchor" href="#phase-4-runtime-抽取"><span>Phase 4: Runtime 抽取</span></a></h2><ul><li>[x] 将 <code>GameServer</code> 重新定义为 runtime host，而不是框架总入口</li><li>[x] 新增 <code>ApplicationHost</code></li><li>[ ] 新增 <code>ServiceHost</code></li><li>[ ] 新增 signal / shutdown hook</li><li>[x] 新增 console event loop 抽象边界</li></ul><h2 id="phase-5-data-抽取" tabindex="-1"><a class="header-anchor" href="#phase-5-data-抽取"><span>Phase 5: Data 抽取</span></a></h2><ul><li>[x] 抽出 <code>apollo_data_core</code></li><li>[x] 迁移 ORM / SQL Template / datasource</li><li>[ ] 迁移 RedisTemplate / cache primitive / distributed lock primitive</li><li>[ ] 移除重复的数据库与 redis 路径</li></ul><h2 id="phase-6-net-抽取" tabindex="-1"><a class="header-anchor" href="#phase-6-net-抽取"><span>Phase 6: Net 抽取</span></a></h2><ul><li>[ ] 收敛 <code>src/network</code> 与 <code>src/apollo/net</code></li><li>[ ] 抽出 <code>apollo_net_core</code></li><li>[ ] 分离 tcp / http / websocket / rpc</li></ul><h2 id="phase-7-game-抽取" tabindex="-1"><a class="header-anchor" href="#phase-7-game-抽取"><span>Phase 7: Game 抽取</span></a></h2><ul><li>[ ] 抽出 <code>apollo_game_core</code></li><li>[ ] 迁移 AOI / scene / movement 到 <code>game/world</code></li><li>[ ] 迁移 attribute / buff / skill / ecs 到 <code>game/battle</code></li><li>[ ] 识别 social / economy 的独立边界</li></ul><h2 id="phase-8-starter-与-app-装配" tabindex="-1"><a class="header-anchor" href="#phase-8-starter-与-app-装配"><span>Phase 8: Starter 与 App 装配</span></a></h2><ul><li>[ ] 为 core/net/mysql/redis 提供 starter</li><li>[ ] 将 <code>apps/game-server</code> 改造成 starter 组合入口</li><li>[ ] 引入 <code>apps/gateway-server</code></li><li>[ ] 引入 <code>apps/login-server</code></li></ul><h2 id="exit-criteria" tabindex="-1"><a class="header-anchor" href="#exit-criteria"><span>Exit Criteria</span></a></h2><ul><li>[ ] 顶层单体 <code>apollo</code> target 仅作为兼容聚合层，或完全退役</li><li>[ ] 新 app 全部通过模块 target + starter 组合构建</li><li>[ ] 模块边界稳定，测试覆盖基础路径</li></ul>`,20)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};